"use client";

import * as React from "react";
import { ArrowDown } from "lucide-react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * JUMP TO LATEST: a chat that follows the answer, until you
 * scroll away
 *
 *   following  pinned to the bottom while text streams in
 *   away       you scrolled up: it lets go at once, and a round
 *              ↓ button appears
 *   new below  text arrived while you were away: the button
 *              widens into "● Writing"; when the answer ends the
 *              label morphs to "New reply"
 *   back       a click glides down, chasing the moving bottom,
 *              and it follows again
 *
 * Wrap your messages. Give it a height (or flex-1) and change
 * followKey when someone sends, to bring them back down.
 * ───────────────────────────────────────────────────────── */

export interface ChatScrollProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  /** True while an answer streams; the button says "Writing". */
  streaming?: boolean;
  /** Change it (e.g. to the latest message id) to jump to the bottom, e.g. after sending. */
  followKey?: React.Key;
  /** How close to the bottom (px) still counts as at the bottom. */
  threshold?: number;
  /** Classes for the inner content column. */
  contentClassName?: string;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function ChatScroll({
  children,
  streaming = false,
  followKey,
  threshold = 48,
  className = "",
  contentClassName = "",
  ...props
}: ChatScrollProps) {
  const reduced = useReducedMotion();
  const scrollerRef = React.useRef<HTMLDivElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const stuck = React.useRef(true);
  const lastTop = React.useRef(0);
  const touchY = React.useRef(0);
  const frame = React.useRef(0);
  const gliding = React.useRef(false);
  // When the person last reached for the scroll; only their own scrolling lets go of the bottom.
  const intent = React.useRef(0);
  const [away, setAway] = React.useState(false);
  const [unread, setUnread] = React.useState(false);

  const distance = () => {
    const el = scrollerRef.current;
    return el ? el.scrollHeight - el.clientHeight - el.scrollTop : 0;
  };

  const release = () => {
    cancelAnimationFrame(frame.current);
    gliding.current = false;
    stuck.current = false;
  };

  /* Glide to the bottom, re-reading it every frame because it moves while text streams in. */
  const toBottom = React.useCallback(
    (smooth: boolean) => {
      const el = scrollerRef.current;
      if (!el) return;
      cancelAnimationFrame(frame.current);
      stuck.current = true;
      setAway(false);
      setUnread(false);
      if (!smooth || reduced) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      gliding.current = true;
      const from = el.scrollTop;
      const start = performance.now();
      const step = (now: number) => {
        const t = Math.min(1, (now - start) / 520);
        const eased = 1 - Math.pow(1 - t, 4);
        el.scrollTop =
          from + (el.scrollHeight - el.clientHeight - from) * eased;
        if (t < 1) frame.current = requestAnimationFrame(step);
        else gliding.current = false;
      };
      frame.current = requestAnimationFrame(step);
    },
    [reduced],
  );

  // Start at the latest message.
  React.useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, []);

  // While following, every bit of new content keeps the bottom in view; while away, it's unread.
  React.useEffect(() => {
    const content = contentRef.current;
    const el = scrollerRef.current;
    if (!content || !el) return;
    const observer = new ResizeObserver(() => {
      if (stuck.current) {
        if (!gliding.current) el.scrollTop = el.scrollHeight;
      } else if (distance() > threshold) {
        setUnread(true);
        setAway(true);
      }
    });
    observer.observe(content);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame.current);
    };
  }, [threshold]);

  // A new message from the person brings them back down.
  const firstKey = React.useRef(followKey);
  React.useEffect(() => {
    if (followKey === firstKey.current) return;
    firstKey.current = followKey;
    toBottom(true);
  }, [followKey, toBottom]);

  const onScroll = () => {
    const el = scrollerRef.current;
    if (!el) return;
    const top = el.scrollTop;
    const d = distance();
    // Upward movement counts only if the person caused it, not when content shrinks and the browser clamps.
    const userUp =
      top < lastTop.current - 1 &&
      !gliding.current &&
      performance.now() - intent.current < 800;
    lastTop.current = top;
    if (userUp) {
      release();
      setAway(d > threshold);
    } else if (!stuck.current && d <= threshold) {
      // Back at the bottom: follow again.
      stuck.current = true;
      setAway(false);
      setUnread(false);
    } else if (!stuck.current) setAway(d > threshold);
  };

  const reach = () => (intent.current = performance.now());

  return (
    <div className={`relative min-h-0 ${className}`} {...props}>
      <div
        ref={scrollerRef}
        tabIndex={0}
        aria-label="Conversation"
        onScroll={onScroll}
        // Let go the moment someone reaches for the scroll, before the next frame of text pulls them down.
        onWheel={(e) => {
          reach();
          if (e.deltaY < 0) release();
        }}
        onTouchStart={(e) => {
          reach();
          touchY.current = e.touches[0]?.clientY ?? 0;
        }}
        onTouchMove={(e) => {
          reach();
          if ((e.touches[0]?.clientY ?? 0) > touchY.current) release();
        }}
        onKeyDown={(e) => {
          reach();
          if (["ArrowUp", "PageUp", "Home"].includes(e.key)) release();
        }}
        // Dragging the scrollbar.
        onPointerDown={reach}
        className="h-full overflow-y-auto overscroll-contain outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/30"
      >
        <div ref={contentRef} className={contentClassName}>
          {children}
        </div>
      </div>

      <div className="pointer-events-none absolute inset-x-0 bottom-3 flex justify-center">
        <button
          type="button"
          inert={!away}
          onClick={() => toBottom(true)}
          aria-label={
            unread
              ? `${streaming ? "Still writing" : "New reply"} below. Jump to latest`
              : "Jump to latest"
          }
          className="cursor-pointer pointer-events-auto flex h-8 items-center rounded-full border border-border bg-background px-2 text-[12.5px] font-medium text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/40 active:scale-[0.96]"
          style={{
            opacity: away ? 1 : 0,
            transform: away ? "none" : "translateY(8px) scale(0.92)",
            transition: reduced
              ? "none"
              : `opacity 220ms ${EASE}, transform 320ms ${EASE}`,
          }}
        >
          {/* The label opens out of the round button; its words morph from "Writing" to "New reply" and the pill follows. */}
          <span
            aria-hidden="true"
            className="grid"
            style={{
              gridTemplateColumns: unread ? "1fr" : "0fr",
              opacity: unread ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 380ms ${EASE}, opacity 260ms ${EASE}`,
            }}
          >
            <span className="flex min-w-0 items-center gap-1.5 overflow-hidden whitespace-nowrap">
              <span className="flex shrink-0 items-center gap-1.5 pl-1 pr-1.5">
                <span className="relative flex size-1.5">
                  <span
                    className={`absolute inset-0 rounded-full bg-primary motion-reduce:animate-none ${streaming ? "animate-[ui-ping_1.4s_cubic-bezier(0,0,0.2,1)_infinite]" : "opacity-0"}`}
                  />
                  <span className="relative size-1.5 rounded-full bg-primary" />
                </span>
                <span
                  className={`transition-colors duration-300 ${streaming ? SHEEN : ""}`}
                >
                  <TextMorph>{streaming ? "Writing" : "New reply"}</TextMorph>
                </span>
              </span>
            </span>
          </span>
          <ArrowDown aria-hidden="true" className="size-4" />
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

